        opp_list = observation.get("opponent_territory") or []
        kmin = 10**9
        # Deterministic sampling up to 6 cells for speed.
        for i in range(0, min(6, len(opp_list))):
            px, py = opp_list[i][0], opp_list[i][1]
            d = abs(int(px) - nx) + abs(int(py) - ny)
            if d < kmin:
                kmin = d
        if kmin == 10**9:
            kmin = abs(ox - nx) + abs(oy - ny)

        sc += 80 * (-kmin)  # smaller distance is better
        sc += int(20 * (-(abs(nx - cx) + abs(ny - cy))))  # favor central slightly

